package com.bank.norm;

import java.util.List;
import java.util.logging.Logger;

// Replaces each word with its shortest matching root code from the Trie.
public class ProductRootNormalizer {

    private static final Logger log = Logger.getLogger(ProductRootNormalizer.class.getName());

    private final TrieNode root = new TrieNode();

    public ProductRootNormalizer(List<String> roots) {
        for (String r : roots) {
            TrieNode node = root;
            for (char c : r.toCharArray()) {
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            }
            node.isWord = true;
        }
    }

    public String normalize(String sentence) {
        String[] words = sentence.split(" ");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) out.append(' ');
            out.append(shortestRoot(words[i]));
        }
        String result = out.toString();
        log.info("Normalized: '" + sentence + "' -> '" + result + "'");
        return result;
    }

    // Walk Trie; return first root hit (shortest prefix) or the word unchanged.
    private String shortestRoot(String word) {
        TrieNode node = root;
        StringBuilder prefix = new StringBuilder();
        for (char c : word.toCharArray()) {
            TrieNode next = node.children.get(c);
            if (next == null) return word;     // no root prefixes this word
            prefix.append(c);
            if (next.isWord) return prefix.toString(); // first = shortest root
            node = next;
        }
        return word;                            // word fully walked, no root end
    }
}
