package com.bank.norm;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class NormalizerDemo {

    private static final Logger log = Logger.getLogger(NormalizerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Product Description Normalizer");
        // Official root codes
        List<String> roots = List.of("sav", "loan", "card");
        ProductRootNormalizer normalizer = new ProductRootNormalizer(roots);

        // Long product words normalized to shortest root
        normalizer.normalize("savings loanaccount cardholder current");
    }
}
